import type { AgeGroup, AttendanceStatus, Child, ChurchEvent, Facilitator, RepeatedAbsentee, RosterChild } from './types'

const statuses: AttendanceStatus[] = ['present', 'absent', 'excused', 'late']
const statusTone = (status?: string | null): 'neutral' | 'success' | 'danger' | 'info' => status === 'present' || status === 'late' ? 'success' : status === 'absent' ? 'danger' : status === 'excused' ? 'info' : 'neutral'

function useChurchScope(): ChurchScope | null {
  const { organization, branch } = useTenant()
  return organization && branch ? { organizationId: tenantId(organization), branchId: branch.id } : null
}
function BranchRequired({ children }: { children: (scope: ChurchScope) => ReactNode }) {
  const scope = useChurchScope()
  if (!scope) return <div className="page-grid"><PageHeader title="Children's Church" /><PageSection><EmptyState title="Select a branch" description="Children's Church records are managed separately for each branch. Use the branch selector above to continue." /></PageSection></div>
  return children(scope)
}
function MutationStatus({ mutation, success }: { mutation: { error: unknown; isSuccess: boolean }; success: string }) {
  if (mutation.error) return <p role="alert" className="field-error">{errorMessage(mutation.error)}</p>
  if (mutation.isSuccess) return <p role="status" className="text-sm text-emerald-700 dark:text-emerald-300">{success}</p>
  return null
}

export function ChurchDashboardPage() {
  return <BranchRequired>{(scope) => <ChurchDashboard scope={scope} />}</BranchRequired>
}
function ChurchDashboard({ scope }: { scope: ChurchScope }) {
  const query = useQuery({ queryKey: churchKeys.resource(scope, 'dashboard'), queryFn: () => churchApi.dashboard(scope) })
  if (query.isLoading) return <div className="page-grid"><Spinner label="Loading church dashboard" /></div>
  if (query.error || !query.data) return <div className="page-grid"><ErrorState message={errorMessage(query.error)} onRetry={() => void query.refetch()} /></div>
  const data = query.data
  const stats = [
    { label: 'Active children', value: data.active_children },
    { label: 'Latest Sunday attended', value: data.recent_attendance.present + data.recent_attendance.late },
    { label: 'Latest Sunday absent', value: data.recent_attendance.absent },
    { label: 'Attendance', value: data.attendance_percentage == null ? '—' : `${data.attendance_percentage}%` },
  ]
  return <div className="page-grid"><PageHeader title="Children's Church" description="Today's services, attendance and upcoming activities." actions={<Link to="/church/sundays"><Button><CalendarDays /> Sunday services</Button></Link>} />
    <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{stats.map((item) => <Card key={item.label} className="p-5"><p className="text-2xl font-bold">{item.value}</p><p className="text-sm text-muted-foreground">{item.label}</p></Card>)}</div>
    {data.upcoming_event ? <PageSection title="Next event"><Link to="/church/events/$eventId" params={{ eventId: data.upcoming_event.id }} className="flex min-h-14 items-center justify-between rounded-lg bg-muted p-4"><span><strong>{data.upcoming_event.name}</strong><span className="block text-sm text-muted-foreground">{friendlyDate(data.upcoming_event.event_date)} · {data.upcoming_event.location || 'Location not set'}</span></span><ChevronRight /></Link></PageSection> : <PageSection><EmptyState title="No upcoming event" description="Create an event or Sunday service to get started." /></PageSection>}
    <div className="grid gap-6 lg:grid-cols-2"><PageSection title="Upcoming events">{data.upcoming_events.length ? <div className="grid gap-2">{data.upcoming_events.map((event) => <Link key={event.id} to="/church/events/$eventId" params={{ eventId: event.id }} className="rounded-lg border p-3 hover:bg-accent"><strong>{event.name}</strong><span className="block text-sm text-muted-foreground">{friendlyDate(event.event_date)}</span></Link>)}</div> : <p className="text-sm text-muted-foreground">None scheduled.</p>}</PageSection><PageSection title="Quick actions"><div className="grid gap-2 sm:grid-cols-2"><Link to="/church/children/new"><Button className="w-full"><Plus /> Register child</Button></Link><Link to="/church/sundays"><Button variant="secondary" className="w-full"><CalendarDays /> Create Sunday</Button></Link><Link to="/church/facilitators"><Button variant="secondary" className="w-full"><Users /> Facilitators</Button></Link><Link to="/church/absenteeism"><Button variant="secondary" className="w-full"><ClipboardCheck /> Absentees</Button></Link></div></PageSection></div>
  </div>
}

const childColumns: DataColumn<Child>[] = [
  { key: 'name', header: 'Child', cell: (row) => <Link to="/church/children/$childId" params={{ childId: row.id }} className="font-semibold text-primary hover:underline">{row.first_name} {row.other_names} {row.last_name}</Link>, sortValue: (row) => `${row.first_name} ${row.last_name}` },
  { key: 'age', header: 'Age', cell: (row) => row.age ?? '—', sortValue: (row) => row.age ?? 0 },
  { key: 'group', header: 'Age group', cell: (row) => row.age_group_name },
  { key: 'guardian', header: 'Guardian', cell: (row) => <><span>{row.guardian_name}</span><span className="block text-xs text-muted-foreground">{row.guardian_contact}</span></> },
  { key: 'status', header: 'Status', cell: (row) => <Badge tone={row.is_active ? 'success' : 'neutral'}>{row.is_active ? 'Active' : 'Inactive'}</Badge> },
]
export function ChildrenPage() { return <BranchRequired>{(scope) => <Children scope={scope} />}</BranchRequired> }
function Children({ scope }: { scope: ChurchScope }) {
  const query = usePaginatedQuery({ queryKey: churchKeys.resource(scope, 'children'), queryFn: (page) => churchApi.children(scope, {}, page) })
  const rows = query.rows
  return <div className="page-grid"><PageHeader title="Children" description="Registered children and guardian contact information." actions={<PermissionGuard require="church-children.manage"><Link to="/church/children/new"><Button><Plus /> Register child</Button></Link></PermissionGuard>} /><PageSection><DataView rows={rows} columns={childColumns} getRowId={(row) => row.id} mobileSummary={(row) => <><Link to="/church/children/$childId" params={{ childId: row.id }} className="font-semibold">{row.first_name} {row.last_name}</Link><p className="text-sm text-muted-foreground">{row.age_group_name} · Age {row.age ?? 'unknown'}</p></>} mobileDetails={(row) => <><span>{row.guardian_name}</span><a href={`tel:${row.guardian_contact}`} className="text-primary">{row.guardian_contact}</a></>} searchableText={(row) => `${row.first_name} ${row.last_name} ${row.other_names} ${row.guardian_name} ${row.guardian_contact}`} loading={query.isLoading} error={query.error ? errorMessage(query.error) : undefined} onRetry={() => void query.refetch()} emptyTitle="No children registered" /></PageSection></div>
}

export function ChildFormPage() { return <BranchRequired>{(scope) => <ChildForm scope={scope} />}</BranchRequired> }
function ChildForm({ scope }: { scope: ChurchScope }) {
  const params = useParams({ strict: false }) as { childId?: UUID }; const childId = params.childId
  const navigate = useNavigate(); const client = useQueryClient()
  const groups = useQuery({ queryKey: churchKeys.resource(scope, 'age-groups', true), queryFn: () => churchApi.ageGroups(scope, true) })
  const child = useQuery({ queryKey: churchKeys.resource(scope, 'child', childId), queryFn: () => churchApi.child(scope, childId as UUID), enabled: Boolean(childId) })
  const mutation = useMutation({ mutationFn: (input: Partial<Child>) => childId ? churchApi.updateChild(scope, childId, input) : churchApi.createChild(scope, input), onSuccess: (saved) => { void client.invalidateQueries({ queryKey: churchKeys.root(scope) }); void navigate({ to: '/church/children/$childId', params: { childId: saved.id } }) } })
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const input: Partial<Child> = { first_name: String(data.get('first_name')), last_name: String(data.get('last_name')), other_names: String(data.get('other_names')), date_of_birth: String(data.get('date_of_birth')), age_group: String(data.get('age_group')), guardian_name: String(data.get('guardian_name')), guardian_contact: String(data.get('guardian_contact')), location: String(data.get('location')), registration_date: String(data.get('registration_date')) }; if (childId) input.is_active = data.get('is_active') === 'on'; mutation.mutate(input) }
  if (childId && child.isLoading) return <div className="page-grid"><Spinner /></div>
  const value = child.data
  return <div className="page-grid"><PageHeader title={childId ? `${value?.first_name || ''} ${value?.last_name || ''}` : 'Register child'} description={childId ? 'Personal, guardian and attendance information.' : 'Add a child to this branch.'} />
    <PageSection title={childId ? 'Personal details' : undefined}><form key={value?.id || 'new'} className="grid gap-4" onSubmit={submit}><div className="grid gap-4 md:grid-cols-3"><FormField label="First name" htmlFor="first_name"><Input id="first_name" name="first_name" defaultValue={value?.first_name} required /></FormField><FormField label="Last name" htmlFor="last_name"><Input id="last_name" name="last_name" defaultValue={value?.last_name} required /></FormField><FormField label="Other names" htmlFor="other_names"><Input id="other_names" name="other_names" defaultValue={value?.other_names} /></FormField></div><div className="grid gap-4 md:grid-cols-3"><FormField label="Guardian name" htmlFor="guardian_name"><Input id="guardian_name" name="guardian_name" defaultValue={value?.guardian_name} required /></FormField><FormField label="Guardian contact" htmlFor="guardian_contact"><Input id="guardian_contact" name="guardian_contact" inputMode="tel" defaultValue={value?.guardian_contact} required /></FormField><FormField label="Area of residence" htmlFor="location"><Input id="location" name="location" defaultValue={value?.location} /></FormField></div><div className="grid gap-4 md:grid-cols-3"><FormField label="Date of birth" htmlFor="date_of_birth"><Input id="date_of_birth" name="date_of_birth" type="date" defaultValue={value?.date_of_birth || ''} required /></FormField><FormField label="Age group" htmlFor="age_group"><Select id="age_group" name="age_group" defaultValue={value?.age_group} required><option value="">Select age group</option>{asList(groups.data || []).map((group) => <option key={group.id} value={group.id}>{group.name}</option>)}</Select></FormField><FormField label="Registration date" htmlFor="registration_date"><Input id="registration_date" name="registration_date" type="date" defaultValue={value?.registration_date || new Date().toISOString().slice(0, 10)} required /></FormField></div>{childId && <label className="flex min-h-11 items-center gap-3"><input name="is_active" type="checkbox" defaultChecked={value?.is_active ?? true} className="h-5 w-5" /> Active registration</label>}<MutationStatus mutation={mutation} success="Child saved." /><FormActions><Link to="/church/children"><Button type="button" variant="secondary">Cancel</Button></Link><Button disabled={mutation.isPending}><Save /> {mutation.isPending ? 'Saving…' : 'Save child'}</Button></FormActions></form></PageSection>
    {value && <PageSection title="Attendance summary"><div className="grid gap-3 sm:grid-cols-3"><Card className="p-4"><strong className="text-xl">{value.statistics?.attended ?? 0}</strong><p className="text-sm text-muted-foreground">Attended</p></Card><Card className="p-4"><strong className="text-xl">{value.statistics?.absent ?? 0}</strong><p className="text-sm text-muted-foreground">Absent</p></Card><Card className="p-4"><strong className="text-xl">{value.statistics?.attendance_percentage ?? '—'}{value.statistics?.attendance_percentage != null ? '%' : ''}</strong><p className="text-sm text-muted-foreground">Attendance</p></Card></div><div className="mt-4 grid gap-2">{value.recent_attendance?.map((record) => <div className="flex items-center justify-between rounded-lg border p-3" key={record.id}><span>{record.service_name || 'Event attendance'}<span className="block text-xs text-muted-foreground">{friendlyDate(record.created_at)}</span></span><Badge tone={statusTone(record.attendance_status)}>{record.attendance_status}</Badge></div>)}</div></PageSection>}
  </div>
}

export function AgeGroupsPage() { return <BranchRequired>{(scope) => <AgeGroups scope={scope} />}</BranchRequired> }
function AgeGroups({ scope }: { scope: ChurchScope }) {
  const client = useQueryClient(); const [editing, setEditing] = useState<AgeGroup | 'new' | null>(null)
  const query = usePaginatedQuery({ queryKey: churchKeys.resource(scope, 'age-groups'), queryFn: (page) => churchApi.ageGroups(scope, undefined, page) })
  const mutation = useMutation({ mutationFn: (input: Partial<AgeGroup>) => editing && editing !== 'new' ? churchApi.updateAgeGroup(scope, editing.id, input) : churchApi.createAgeGroup(scope, input), onSuccess: () => { setEditing(null); void client.invalidateQueries({ queryKey: churchKeys.resource(scope, 'age-groups') }) } })
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); mutation.mutate({ name: String(data.get('name')), minimum_age: Number(data.get('minimum_age')), maximum_age: Number(data.get('maximum_age')), is_active: data.get('is_active') === 'on' }) }
  const rows = query.rows; const current = editing === 'new' ? null : editing
  return <div className="page-grid"><PageHeader title="Age groups" description="Configure the age ranges used to organise children." actions={<PermissionGuard require="church-age-groups.manage"><Button onClick={() => setEditing('new')}><Plus /> Add age group</Button></PermissionGuard>} /><PageSection><DataView rows={rows} columns={[{ key: 'name', header: 'Name', cell: (row) => row.name }, { key: 'range', header: 'Age range', cell: (row) => `${row.minimum_age}–${row.maximum_age}` }, { key: 'status', header: 'Status', cell: (row) => <Badge tone={row.is_active ? 'success' : 'neutral'}>{row.is_active ? 'Active' : 'Inactive'}</Badge> }]} getRowId={(row) => row.id} mobileSummary={(row) => <strong>{row.name}</strong>} mobileDetails={(row) => `Ages ${row.minimum_age}–${row.maximum_age}`} actions={(row) => <PermissionGuard require="church-age-groups.manage"><Button variant="secondary" onClick={() => setEditing(row)}>Edit</Button></PermissionGuard>} loading={query.isLoading} error={query.error ? errorMessage(query.error) : undefined} /></PageSection><Modal open={editing !== null} onClose={() => setEditing(null)} title={current ? `Edit ${current.name}` : 'Add age group'}><form key={current?.id || 'new'} className="grid gap-4" onSubmit={submit}><FormField label="Name" htmlFor="group-name"><Input id="group-name" name="name" defaultValue={current?.name} required /></FormField><div className="grid grid-cols-2 gap-3"><FormField label="Minimum age" htmlFor="min-age"><Input id="min-age" name="minimum_age" type="number" min="0" defaultValue={current?.minimum_age} required /></FormField><FormField label="Maximum age" htmlFor="max-age"><Input id="max-age" name="maximum_age" type="number" min="0" defaultValue={current?.maximum_age} required /></FormField></div><label className="flex min-h-11 items-center gap-3"><input name="is_active" type="checkbox" defaultChecked={current?.is_active ?? true} className="h-5 w-5" /> Active</label><MutationStatus mutation={mutation} success="Age group saved." /><FormActions><Button type="button" variant="secondary" onClick={() => setEditing(null)}>Cancel</Button><Button disabled={mutation.isPending}>{mutation.isPending ? 'Saving…' : 'Save age group'}</Button></FormActions></form></Modal></div>
}

const eventColumns: DataColumn<ChurchEvent>[] = [
  { key: 'name', header: 'Event', cell: (row) => <Link to="/church/events/$eventId" params={{ eventId: row.id }} className="font-semibold text-primary hover:underline">{row.name}</Link>, sortValue: (row) => row.name },
  { key: 'date', header: 'Date', cell: (row) => friendlyDate(row.event_date), sortValue: (row) => row.event_date },
  { key: 'type', header: 'Type', cell: (row) => row.event_type.replaceAll('_', ' ') },
  { key: 'status', header: 'Status', cell: (row) => <Badge tone={row.status === 'cancelled' ? 'danger' : row.status === 'completed' ? 'success' : 'info'}>{row.status.replaceAll('_', ' ')}</Badge> },
]
export function EventsPage() { return <BranchRequired>{(scope) => <Events scope={scope} />}</BranchRequired> }
function Events({ scope }: { scope: ChurchScope }) {
  const client = useQueryClient(); const [filters, setFilters] = useState({ event_type: '', status: '', date: '' }); const [search, setSearch] = useState(''); const [open, setOpen] = useState(false)
  const [sessions, setSessions] = useState([{ name: 'Morning Service', start_time: '08:00', end_time: '09:30' }, { name: '10am Service', start_time: '10:00', end_time: '11:30' }, { name: 'Midday Service', start_time: '12:00', end_time: '13:30' }, { name: 'Afternoon Service', start_time: '15:00', end_time: '16:30' }])
  const activeFilters = Object.fromEntries(Object.entries(filters).filter(([, value]) => value)); const query = usePaginatedQuery({ queryKey: churchKeys.resource(scope, 'events', activeFilters), queryFn: (page) => churchApi.events(scope, activeFilters, page) }); const rows = query.rows
  const createSunday = useMutation({ mutationFn: (input: Parameters<typeof churchApi.createSunday>[1]) => churchApi.createSunday(scope, input), onSuccess: () => { setOpen(false); void client.invalidateQueries({ queryKey: churchKeys.root(scope) }) } })
  const submitSunday = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); createSunday.mutate({ sunday_date: String(data.get('sunday_date')), name: String(data.get('name')), location: String(data.get('location')), sessions: sessions.map((item, index) => ({ ...item, end_time: item.end_time || null, service_order: index + 1 })) }) }
  return <div className="page-grid"><PageHeader title="Events" description="Sunday services and other children's church activities in one calendar." actions={<PermissionGuard require="church-events.manage"><div className="flex flex-wrap gap-2"><Button variant="secondary" onClick={() => setOpen(true)}><CalendarDays /> Create Sunday</Button><Link to="/church/events/new"><Button><Plus /> Create event</Button></Link></div></PermissionGuard>} /><PageSection><div className="mb-4 grid gap-3 md:grid-cols-4"><FormField label="Search" htmlFor="event-filter-search"><Input id="event-filter-search" type="search" placeholder="Name, location, or type" value={search} onChange={(e) => setSearch(e.target.value)} /></FormField><FormField label="Type" htmlFor="event-filter-type"><Select id="event-filter-type" value={filters.event_type} onChange={(e) => setFilters({ ...filters, event_type: e.target.value })}><option value="">All types</option><option value="sunday_service">Sunday service</option>{['outreach', 'conference', 'camp', 'training', 'rehearsal', 'special_service', 'trip', 'other'].map((type) => <option key={type} value={type}>{type.replaceAll('_', ' ')}</option>)}</Select></FormField><FormField label="Status" htmlFor="event-filter-status"><Select id="event-filter-status" value={filters.status} onChange={(e) => setFilters({ ...filters, status: e.target.value })}><option value="">All statuses</option>{['draft', 'scheduled', 'in_progress', 'completed', 'cancelled'].map((status) => <option key={status} value={status}>{status.replaceAll('_', ' ')}</option>)}</Select></FormField><FormField label="Date" htmlFor="event-filter-date"><Input id="event-filter-date" type="date" value={filters.date} onChange={(e) => setFilters({ ...filters, date: e.target.value })} /></FormField></div><DataView rows={rows} columns={eventColumns} getRowId={(row) => row.id} mobileSummary={(row) => <><Link to="/church/events/$eventId" params={{ eventId: row.id }} className="font-semibold">{row.name}</Link><p className="text-sm text-muted-foreground">{friendlyDate(row.event_date)}</p></>} mobileDetails={(row) => <div className="flex items-center justify-between"><span className="capitalize">{row.event_type.replaceAll('_', ' ')}</span><Badge>{row.status}</Badge></div>} searchableText={(row) => `${row.name} ${row.location} ${row.event_type}`} searchValue={search} showSearchInput={false} loading={query.isLoading} error={query.error ? errorMessage(query.error) : undefined} hasMore={query.hasMore} loadingMore={query.isFetchingNextPage} onLoadMore={() => void query.fetchNextPage()} /></PageSection><Modal open={open} onClose={() => setOpen(false)} title="Create Sunday" description="Use this fallback when the automatic Saturday schedule has not run."><form className="grid gap-4" onSubmit={submitSunday}><FormField label="Sunday date" htmlFor="manual-sunday-date"><Input id="manual-sunday-date" name="sunday_date" type="date" required /></FormField><FormField label="Event name" htmlFor="manual-sunday-name"><Input id="manual-sunday-name" name="name" /></FormField><FormField label="Location" htmlFor="manual-sunday-location"><Input id="manual-sunday-location" name="location" /></FormField><div className="grid gap-3">{sessions.map((session, index) => <div className="rounded-lg border p-3" key={index}><div className="grid gap-2"><Input aria-label={`Service ${index + 1} name`} value={session.name} onChange={(e) => setSessions((items) => items.map((item, i) => i === index ? { ...item, name: e.target.value } : item))} required /><div className="grid grid-cols-2 gap-2"><Input aria-label={`Service ${index + 1} start`} type="time" value={session.start_time} onChange={(e) => setSessions((items) => items.map((item, i) => i === index ? { ...item, start_time: e.target.value } : item))} required /><Input aria-label={`Service ${index + 1} end`} type="time" value={session.end_time} onChange={(e) => setSessions((items) => items.map((item, i) => i === index ? { ...item, end_time: e.target.value } : item))} /></div></div></div>)}</div><MutationStatus mutation={createSunday} success="Sunday created." /><FormActions><Button type="button" variant="secondary" onClick={() => setOpen(false)}>Cancel</Button><Button disabled={createSunday.isPending}>Create Sunday</Button></FormActions></form></Modal></div>
}

export function EventFormPage() { return <BranchRequired>{(scope) => <EventForm scope={scope} />}</BranchRequired> }
function EventForm({ scope }: { scope: ChurchScope }) {
  const params = useParams({ strict: false }) as { eventId?: UUID }; const eventId = params.eventId
  const navigate = useNavigate(); const client = useQueryClient()
  const eventQuery = useQuery({ queryKey: churchKeys.resource(scope, 'event', eventId), queryFn: () => churchApi.event(scope, eventId as UUID), enabled: Boolean(eventId) })
  const mutation = useMutation({ mutationFn: (input: Partial<ChurchEvent>) => eventId ? churchApi.updateEvent(scope, eventId, input) : churchApi.createEvent(scope, input), onSuccess: (saved) => { void client.invalidateQueries({ queryKey: churchKeys.root(scope) }); void navigate({ to: '/church/events/$eventId', params: { eventId: saved.id } }) } })
  const finalize = useMutation({ mutationFn: () => churchApi.finalizeSunday(scope, eventId as UUID), onSuccess: () => void client.invalidateQueries({ queryKey: churchKeys.root(scope) }) })
  const submit = (formEvent: FormEvent<HTMLFormElement>) => { formEvent.preventDefault(); const data = new FormData(formEvent.currentTarget); mutation.mutate({ name: String(data.get('name')), event_type: String(data.get('event_type')), description: String(data.get('description')), event_date: String(data.get('event_date')), start_time: String(data.get('start_time')) || null, end_time: String(data.get('end_time')) || null, location: String(data.get('location')), status: String(data.get('status')) } as Partial<ChurchEvent>) }
  const value = eventQuery.data
  if (eventId && eventQuery.isLoading) return <div className="page-grid"><Spinner /></div>
  if (value?.event_type === 'sunday_service') return <div className="page-grid"><PageHeader title={value.name} description={`${friendlyDate(value.event_date)} · ${value.location || 'Location not set'}`} actions={!value.attendance_finalized_at ? <PermissionGuard require="church-attendance.manage"><Button variant="secondary" onClick={() => { if (window.confirm('Finish attendance and mark children with no attendance record absent?')) finalize.mutate() }}>Finish Sunday attendance</Button></PermissionGuard> : <Badge tone="success">Attendance finalized</Badge>} /><PageSection title="Service sessions"><SessionCards event={value} /></PageSection><MutationStatus mutation={finalize} success="Sunday attendance finalized." /></div>
  return <div className="page-grid"><PageHeader title={eventId ? value?.name || 'Event' : 'Create event'} description={value?.event_type === 'sunday_service' ? `${friendlyDate(value.event_date)} · ${value.location || 'Location not set'}` : 'Create or edit an ordinary church event.'} actions={value?.event_type === 'sunday_service' ? (!value.attendance_finalized_at ? <PermissionGuard require="church-attendance.manage"><Button variant="secondary" onClick={() => { if (window.confirm('Finish attendance and mark children with no attendance record absent?')) finalize.mutate() }}>Finish Sunday attendance</Button></PermissionGuard> : <Badge tone="success">Attendance finalized</Badge>) : undefined} />
    <PageSection><form key={value?.id || 'new'} className="grid gap-4" onSubmit={submit}><FormField label="Event name" htmlFor="event-name"><Input id="event-name" name="name" defaultValue={value?.name} required /></FormField><div className="grid gap-4 sm:grid-cols-2"><FormField label="Type" htmlFor="event-type"><Select id="event-type" name="event_type" defaultValue={value?.event_type || 'outreach'}>{['outreach', 'conference', 'camp', 'training', 'rehearsal', 'special_service', 'trip', 'other'].map((type) => <option value={type} key={type}>{type.replaceAll('_', ' ')}</option>)}</Select></FormField><FormField label="Status" htmlFor="event-status"><Select id="event-status" name="status" defaultValue={value?.status || 'scheduled'}>{['draft', 'scheduled', 'in_progress', 'completed', 'cancelled'].map((item) => <option value={item} key={item}>{item.replaceAll('_', ' ')}</option>)}</Select></FormField></div><FormField label="Date" htmlFor="event-date"><Input id="event-date" name="event_date" type="date" defaultValue={value?.event_date} required /></FormField><div className="grid gap-4 sm:grid-cols-2"><FormField label="Start time" htmlFor="start-time"><Input id="start-time" name="start_time" type="time" defaultValue={value?.start_time || ''} /></FormField><FormField label="End time" htmlFor="end-time"><Input id="end-time" name="end_time" type="time" defaultValue={value?.end_time || ''} /></FormField></div><FormField label="Location" htmlFor="event-location"><Input id="event-location" name="location" defaultValue={value?.location} /></FormField><FormField label="Description" htmlFor="event-description"><Textarea id="event-description" name="description" defaultValue={value?.description} /></FormField><MutationStatus mutation={mutation} success="Event saved." /><FormActions><Link to="/church/events"><Button type="button" variant="secondary">Cancel</Button></Link><Button disabled={mutation.isPending}><Save /> Save event</Button></FormActions></form></PageSection>
    <MutationStatus mutation={finalize} success="Sunday attendance finalized." />{value && value.event_type !== 'sunday_service' && <PageSection title="Event attendance" description="Record attendance directly against this event."><Link to="/church/events/$eventId/attendance" params={{ eventId: value.id }}><Button><ClipboardCheck /> Take event attendance</Button></Link></PageSection>}{value?.sessions?.length ? <PageSection title="Service sessions"><SessionCards event={value} /></PageSection> : null}
  </div>
}

function SessionCards({ event }: { event: ChurchEvent }) {
  return <div className="grid gap-3 sm:grid-cols-2">{event.sessions.map((session) => <Card className="p-4" key={session.id}><div className="flex items-start justify-between gap-3"><div><h3 className="font-semibold">{session.name}</h3><p className="text-sm text-muted-foreground">{friendlyTime(session.start_time)}{session.end_time ? `–${friendlyTime(session.end_time)}` : ''}</p></div><Badge>{session.status}</Badge></div><div className="mt-3 grid grid-cols-2 gap-2 text-sm"><span>Children present <strong>{(session.attendance_summary?.present || 0) + (session.attendance_summary?.late || 0)}</strong></span><span>Absent <strong>{session.attendance_summary?.absent || 0}</strong></span><span>Facilitators <strong>{session.facilitators_assigned || 0}</strong></span><span>Facilitators present <strong>{session.facilitators_present || 0}</strong></span></div><div className="mt-4 grid gap-2 sm:grid-cols-2"><Link to="/church/sessions/$sessionId/attendance" params={{ sessionId: session.id }}><Button className="w-full"><ClipboardCheck /> Attendance</Button></Link><Link to="/church/sessions/$sessionId/facilitators" params={{ sessionId: session.id }}><Button variant="secondary" className="w-full"><Users /> Facilitators</Button></Link></div></Card>)}</div>
}

export function SundaysPage() { return <BranchRequired>{(scope) => <Sundays scope={scope} />}</BranchRequired> }
function Sundays({ scope }: { scope: ChurchScope }) {
  const client = useQueryClient(); const [open, setOpen] = useState(false); const [sessions, setSessions] = useState([{ name: 'First Service', start_time: '08:00', end_time: '' }])
  const query = usePaginatedQuery({ queryKey: churchKeys.resource(scope, 'sundays'), queryFn: (page) => churchApi.events(scope, { event_type: 'sunday_service' }, page) })
  const mutation = useMutation({ mutationFn: (input: Parameters<typeof churchApi.createSunday>[1]) => churchApi.createSunday(scope, input), onSuccess: () => { void client.invalidateQueries({ queryKey: churchKeys.root(scope) }); setSessions([{ name: 'First Service', start_time: '08:00', end_time: '' }]); setOpen(false) } })
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); mutation.mutate({ sunday_date: String(data.get('sunday_date')), name: String(data.get('name')), location: String(data.get('location')), sessions: sessions.map((item, index) => ({ ...item, end_time: item.end_time || null, service_order: index + 1 })) }) }
  const rows = query.rows
  return <div className="page-grid"><PageHeader title="Sunday services" description="Create each Sunday explicitly and manage its individual service sessions." actions={<PermissionGuard require="church-events.manage"><Button onClick={() => setOpen(true)}><Plus /> Create Sunday</Button></PermissionGuard>} /><PageSection><DataView rows={rows} columns={eventColumns} getRowId={(row) => row.id} mobileSummary={(row) => <Link to="/church/sundays/$eventId" params={{ eventId: row.id }} className="font-semibold">{row.name}</Link>} mobileDetails={(row) => `${friendlyDate(row.event_date)} · ${row.sessions.length} service${row.sessions.length === 1 ? '' : 's'}`} actions={(row) => <Link to="/church/sundays/$eventId" params={{ eventId: row.id }}><Button variant="secondary">Open</Button></Link>} loading={query.isLoading} error={query.error ? errorMessage(query.error) : undefined} /></PageSection><Modal open={open} onClose={() => setOpen(false)} title="Create Sunday"><form className="grid gap-4" onSubmit={submit}><FormField label="Sunday date" htmlFor="sunday-date"><Input id="sunday-date" name="sunday_date" type="date" required /></FormField><FormField label="Event name" htmlFor="sunday-name" help="Leave blank for an automatic name."><Input id="sunday-name" name="name" /></FormField><FormField label="Location" htmlFor="sunday-location"><Input id="sunday-location" name="location" /></FormField><div className="grid gap-3"><div className="flex items-center justify-between"><h3 className="font-semibold">Services</h3><Button type="button" variant="secondary" onClick={() => setSessions((items) => [...items, { name: `${items.length + 1} Service`, start_time: '', end_time: '' }])}><Plus /> Add</Button></div>{sessions.map((session, index) => <div className="rounded-lg border p-3" key={index}><p className="mb-2 text-xs font-semibold text-muted-foreground">Service {index + 1}</p><div className="grid gap-2"><Input aria-label={`Service ${index + 1} name`} value={session.name} onChange={(e) => setSessions((items) => items.map((item, i) => i === index ? { ...item, name: e.target.value } : item))} required /><div className="grid grid-cols-2 gap-2"><Input aria-label={`Service ${index + 1} start`} type="time" value={session.start_time} onChange={(e) => setSessions((items) => items.map((item, i) => i === index ? { ...item, start_time: e.target.value } : item))} required /><Input aria-label={`Service ${index + 1} end`} type="time" value={session.end_time} onChange={(e) => setSessions((items) => items.map((item, i) => i === index ? { ...item, end_time: e.target.value } : item))} /></div>{sessions.length > 1 && <Button type="button" variant="ghost" onClick={() => setSessions((items) => items.filter((_, i) => i !== index))}>Remove</Button>}</div></div>)}</div><MutationStatus mutation={mutation} success="Sunday services created." /><FormActions><Button type="button" variant="secondary" onClick={() => setOpen(false)}>Cancel</Button><Button disabled={mutation.isPending}><CalendarDays /> {mutation.isPending ? 'Creating…' : 'Create Sunday'}</Button></FormActions></form></Modal></div>
}

export function SundayDetailPage() { return <BranchRequired>{(scope) => <SundayDetail scope={scope} />}</BranchRequired> }
function SundayDetail({ scope }: { scope: ChurchScope }) {
  const { eventId } = useParams({ strict: false }) as { eventId: UUID }; const client = useQueryClient()
  const query = useQuery({ queryKey: churchKeys.resource(scope, 'event', eventId), queryFn: () => churchApi.event(scope, eventId) })
  const finalize = useMutation({ mutationFn: () => churchApi.finalizeSunday(scope, eventId), onSuccess: () => void client.invalidateQueries({ queryKey: churchKeys.root(scope) }) })
  if (query.isLoading) return <div className="page-grid"><Spinner /></div>
  if (!query.data || query.error) return <div className="page-grid"><ErrorState message={errorMessage(query.error)} /></div>
  const event = query.data
  return <div className="page-grid"><PageHeader title={event.name} description={`${friendlyDate(event.event_date)} · ${event.location || 'Location not set'}`} actions={!event.attendance_finalized_at ? <PermissionGuard require="church-attendance.manage"><Button variant="secondary" onClick={() => { if (window.confirm('Finish attendance and mark children with no attendance record absent?')) finalize.mutate() }}>Finish Sunday attendance</Button></PermissionGuard> : <Badge tone="success">Attendance finalized</Badge>} /><PageSection title="Services"><SessionCards event={event} /></PageSection><MutationStatus mutation={finalize} success="Sunday attendance finalized." /></div>
}

export function AttendancePage() { return <BranchRequired>{(scope) => <Attendance scope={scope} />}</BranchRequired> }
function Attendance({ scope }: { scope: ChurchScope }) {
  const { sessionId } = useParams({ strict: false }) as { sessionId: UUID }; const client = useQueryClient()
  const [search, setSearch] = useState(''); const [group, setGroup] = useState(''); const [includeAttended, setIncludeAttended] = useState(false)
  const [changes, setChanges] = useState<Record<UUID, AttendanceStatus>>({})
  const groups = useQuery({ queryKey: churchKeys.resource(scope, 'age-groups', true), queryFn: () => churchApi.ageGroups(scope, true) })
  const roster = useQuery({ queryKey: churchKeys.resource(scope, 'roster', { sessionId, search, group, includeAttended }), queryFn: () => churchApi.roster(scope, sessionId, { search, age_group: group, include_already_attended: includeAttended }) })
  const save = useMutation({ mutationFn: () => churchApi.saveAttendance(scope, sessionId, Object.entries(changes).map(([child_id, attendance_status]) => ({ child_id, attendance_status }))), onSuccess: () => { setChanges({}); void client.invalidateQueries({ queryKey: churchKeys.root(scope) }) } })
  useEffect(() => { const warn = (event: BeforeUnloadEvent) => { if (Object.keys(changes).length) event.preventDefault() }; window.addEventListener('beforeunload', warn); return () => window.removeEventListener('beforeunload', warn) }, [changes])
  const rows = roster.data?.children || []
  const current = (child: RosterChild) => changes[child.child_id] || child.attendance_status
  const markVisible = () => setChanges((value) => markVisiblePresent(value, rows))
  return <div className="page-grid pb-28"><PageHeader title={roster.data?.session.name || 'Take attendance'} description={roster.data?.session ? `${friendlyDate(roster.data.session.event_date)} · ${friendlyTime(roster.data.session.start_time)}` : 'Loading service roster…'} actions={<Button variant="secondary" onClick={markVisible} disabled={!rows.length}><Check /> Mark visible present</Button>} />
    <div className="sticky top-16 z-20 grid gap-3 border-y bg-background/95 py-3 backdrop-blur sm:grid-cols-[1fr_15rem_auto]"><Input aria-label="Search children" placeholder="Search child name…" value={search} onChange={(event) => setSearch(event.target.value)} /><Select aria-label="Filter by age group" value={group} onChange={(event) => setGroup(event.target.value)}><option value="">All age groups</option>{asList(groups.data || []).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</Select><label className="flex min-h-11 items-center gap-2 rounded-lg border px-3 text-sm"><input type="checkbox" checked={includeAttended} onChange={(event) => setIncludeAttended(event.target.checked)} /> Show other-service attendees</label></div>
    {roster.isLoading ? <Spinner label="Loading roster" /> : roster.error ? <ErrorState message={errorMessage(roster.error)} onRetry={() => void roster.refetch()} /> : !rows.length ? <PageSection><EmptyState title="No children match this roster" /></PageSection> : <div className="grid gap-3">{rows.map((child) => <Card className="p-4" key={child.child_id}><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><h3 className="font-semibold">{child.name}</h3><p className="text-sm text-muted-foreground">{child.age_group_name} · Age {child.age ?? 'unknown'} · <a href={`tel:${child.guardian_contact}`} className="text-primary">{child.guardian_contact}</a></p></div><div className="grid grid-cols-2 gap-2 sm:flex">{statuses.map((statusValue) => <Button type="button" key={statusValue} variant={current(child) === statusValue ? statusValue === 'absent' ? 'danger' : 'primary' : 'secondary'} className="capitalize" onClick={() => setChanges((value) => ({ ...value, [child.child_id]: statusValue }))}>{statusValue}</Button>)}</div></div></Card>)}</div>}
    <div className="fixed inset-x-0 bottom-0 z-30 border-t bg-background/95 p-3 backdrop-blur lg:left-64"><div className="mx-auto flex max-w-7xl items-center justify-between gap-3"><div><p className="font-semibold">{Object.keys(changes).length} unsaved change{Object.keys(changes).length === 1 ? '' : 's'}</p>{save.error && <p className="field-error">{errorMessage(save.error)}</p>}</div><Button disabled={!Object.keys(changes).length || save.isPending} onClick={() => save.mutate()}><Save /> {save.isPending ? 'Saving…' : 'Save attendance'}</Button></div></div>
  </div>
}

export function EventAttendancePage() { return <BranchRequired>{(scope) => <EventAttendance scope={scope} />}</BranchRequired> }
function EventAttendance({ scope }: { scope: ChurchScope }) {
  const { eventId } = useParams({ strict: false }) as { eventId: UUID }; const client = useQueryClient()
  const [search, setSearch] = useState(''); const [group, setGroup] = useState(''); const [changes, setChanges] = useState<Record<UUID, AttendanceStatus>>({})
  const groups = useQuery({ queryKey: churchKeys.resource(scope, 'age-groups', true), queryFn: () => churchApi.ageGroups(scope, true) })
  const roster = useQuery({ queryKey: churchKeys.resource(scope, 'event-roster', { eventId, search, group }), queryFn: () => churchApi.eventRoster(scope, eventId, { search, age_group: group }) })
  const save = useMutation({ mutationFn: () => churchApi.saveEventAttendance(scope, eventId, Object.entries(changes).map(([child_id, attendance_status]) => ({ child_id, attendance_status }))), onSuccess: () => { setChanges({}); void client.invalidateQueries({ queryKey: churchKeys.root(scope) }) } })
  const rows = roster.data?.children || []; const current = (child: RosterChild) => changes[child.child_id] || child.attendance_status
  return <div className="page-grid pb-28"><PageHeader title={roster.data?.event.name || 'Event attendance'} description={roster.data?.event ? friendlyDate(roster.data.event.event_date) : 'Loading event roster…'} actions={<Button variant="secondary" onClick={() => setChanges((value) => markVisiblePresent(value, rows))}><Check /> Mark visible present</Button>} /><div className="grid gap-3 sm:grid-cols-2"><Input aria-label="Search children" placeholder="Search child name…" value={search} onChange={(event) => setSearch(event.target.value)} /><Select aria-label="Filter by age group" value={group} onChange={(event) => setGroup(event.target.value)}><option value="">All age groups</option>{asList(groups.data || []).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</Select></div>{roster.isLoading ? <Spinner /> : roster.error ? <ErrorState message={errorMessage(roster.error)} /> : <div className="mt-4 grid gap-3">{rows.map((child) => <Card className="p-4" key={child.child_id}><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><strong>{child.name}</strong><p className="text-sm text-muted-foreground">{child.age_group_name} · {child.guardian_contact}</p></div><div className="grid grid-cols-2 gap-2 sm:flex">{statuses.map((value) => <Button key={value} variant={current(child) === value ? value === 'absent' ? 'danger' : 'primary' : 'secondary'} className="capitalize" onClick={() => setChanges((state) => ({ ...state, [child.child_id]: value }))}>{value}</Button>)}</div></div></Card>)}</div>}<div className="fixed inset-x-0 bottom-0 z-30 border-t bg-background/95 p-3 lg:left-64"><div className="mx-auto flex max-w-7xl items-center justify-between"><span>{Object.keys(changes).length} unsaved</span><Button disabled={!Object.keys(changes).length || save.isPending} onClick={() => save.mutate()}><Save /> Save attendance</Button></div></div></div>
}

export function FacilitatorsPage() { return <BranchRequired>{(scope) => <Facilitators scope={scope} />}</BranchRequired> }
function Facilitators({ scope }: { scope: ChurchScope }) {
  const client = useQueryClient(); const [editing, setEditing] = useState<Facilitator | 'new' | null>(null)
  const facilitators = usePaginatedQuery({ queryKey: churchKeys.resource(scope, 'facilitators'), queryFn: (page) => churchApi.facilitators(scope, page) })
  const members = useQuery({ queryKey: churchKeys.resource(scope, 'branch-members'), queryFn: () => membersApi.branchMemberships(scope.organizationId, scope.branchId) })
  const groups = useQuery({ queryKey: churchKeys.resource(scope, 'age-groups', true), queryFn: () => churchApi.ageGroups(scope, true) })
  const mutation = useMutation({ mutationFn: (input: Partial<Facilitator> & { user?: UUID }) => editing && editing !== 'new' ? churchApi.updateFacilitator(scope, editing.id, input) : churchApi.createFacilitator(scope, input as Parameters<typeof churchApi.createFacilitator>[1]), onSuccess: () => { setEditing(null); void client.invalidateQueries({ queryKey: churchKeys.resource(scope, 'facilitators') }) } })
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const input: Partial<Facilitator> & { user?: UUID } = { default_age_group: String(data.get('default_age_group')) || null, notes: String(data.get('notes')), is_active: data.get('is_active') === 'on' }; if (editing === 'new') input.user = String(data.get('user')); else Object.assign(input, { first_name: String(data.get('first_name')), last_name: String(data.get('last_name')), email: String(data.get('email')), phone_number: String(data.get('phone_number')) }); mutation.mutate(input) }
  const rows = facilitators.rows; const current = editing === 'new' ? null : editing
  return <div className="page-grid"><PageHeader title="Facilitators" description="Facilitator profiles reuse existing user accounts and branch membership." actions={<PermissionGuard require="church-facilitators.manage"><Button onClick={() => setEditing('new')}><Plus /> Add facilitator</Button></PermissionGuard>} /><PageSection><DataView rows={rows} columns={[{ key: 'name', header: 'Facilitator', cell: (row) => <><Link to="/church/facilitators/$facilitatorId" params={{ facilitatorId: row.id }} className="font-semibold text-primary">{row.name}</Link><span className="block text-xs text-muted-foreground">{row.email}</span></> }, { key: 'group', header: 'Default age group', cell: (row) => row.default_age_group_name || 'All groups' }, { key: 'status', header: 'Status', cell: (row) => <Badge tone={row.is_active ? 'success' : 'neutral'}>{row.is_active ? 'Active' : 'Inactive'}</Badge> }]} getRowId={(row) => row.id} mobileSummary={(row) => <><Link to="/church/facilitators/$facilitatorId" params={{ facilitatorId: row.id }} className="font-semibold">{row.name}</Link><p className="text-sm text-muted-foreground">{row.email}</p></>} mobileDetails={(row) => row.default_age_group_name || 'All age groups'} searchableText={(row) => `${row.name} ${row.email} ${row.phone_number}`} actions={(row) => <PermissionGuard require="church-facilitators.manage"><Button variant="secondary" onClick={() => setEditing(row)}>Edit</Button></PermissionGuard>} loading={facilitators.isLoading} error={facilitators.error ? errorMessage(facilitators.error) : undefined} /></PageSection><Modal open={editing !== null} onClose={() => setEditing(null)} title={current ? `Edit ${current.name}` : 'Add facilitator'}><form key={current?.id || 'new'} className="grid gap-4" onSubmit={submit}>{editing === 'new' ? <FormField label="Branch member" htmlFor="facilitator-user"><Select id="facilitator-user" name="user" required><option value="">Select member</option>{asList(members.data || []).filter((member) => member.is_active).map((member) => <option key={member.id} value={member.user_id}>{member.user_email}</option>)}</Select></FormField> : <><div className="grid gap-4 sm:grid-cols-2"><FormField label="First name" htmlFor="facilitator-first-name"><Input id="facilitator-first-name" name="first_name" defaultValue={current?.first_name} required /></FormField><FormField label="Last name" htmlFor="facilitator-last-name"><Input id="facilitator-last-name" name="last_name" defaultValue={current?.last_name} required /></FormField></div><FormField label="Email" htmlFor="facilitator-email"><Input id="facilitator-email" name="email" type="email" defaultValue={current?.email} required /></FormField><FormField label="Phone" htmlFor="facilitator-phone"><Input id="facilitator-phone" name="phone_number" defaultValue={current?.phone_number} /></FormField></>}<FormField label="Default age group" htmlFor="facilitator-group"><Select id="facilitator-group" name="default_age_group" defaultValue={current?.default_age_group || ''}><option value="">All age groups</option>{asList(groups.data || []).map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</Select></FormField><FormField label="Notes" htmlFor="facilitator-notes"><Textarea id="facilitator-notes" name="notes" defaultValue={current?.notes} /></FormField><label className="flex min-h-11 items-center gap-3"><input type="checkbox" name="is_active" defaultChecked={current?.is_active ?? true} /> Active</label><MutationStatus mutation={mutation} success="Facilitator saved." /><FormActions><Button type="button" variant="secondary" onClick={() => setEditing(null)}>Cancel</Button><Button disabled={mutation.isPending}>{mutation.isPending ? 'Saving…' : 'Save facilitator'}</Button></FormActions></form></Modal></div>
}

export function FacilitatorDetailPage() { return <BranchRequired>{(scope) => <FacilitatorDetail scope={scope} />}</BranchRequired> }
function FacilitatorDetail({ scope }: { scope: ChurchScope }) {
  const { facilitatorId } = useParams({ strict: false }) as { facilitatorId: UUID }; const client = useQueryClient()
  const facilitator = useQuery({ queryKey: churchKeys.resource(scope, 'facilitator', facilitatorId), queryFn: () => churchApi.facilitator(scope, facilitatorId) })
  const groups = useQuery({ queryKey: churchKeys.resource(scope, 'age-groups', true), queryFn: () => churchApi.ageGroups(scope, true) })
  const assignments = useQuery({ queryKey: churchKeys.resource(scope, 'facilitator-assignments', facilitatorId), queryFn: () => churchApi.facilitatorAssignments(scope, facilitatorId) })
  const mutation = useMutation({ mutationFn: (input: Partial<Facilitator>) => churchApi.updateFacilitator(scope, facilitatorId, input), onSuccess: () => void client.invalidateQueries({ queryKey: churchKeys.root(scope) }) })
  if (!facilitator.data) return <div className="page-grid"><Spinner /></div>
  const value = facilitator.data
  return <div className="page-grid"><PageHeader title={value.name} description={`${value.email} · ${value.phone_number || 'No phone number'}`} /><div className="grid gap-6 lg:grid-cols-2"><PageSection title="Facilitator details"><form className="grid gap-4" onSubmit={(event) => { event.preventDefault(); const data = new FormData(event.currentTarget); mutation.mutate({ default_age_group: String(data.get('default_age_group')) || null, notes: String(data.get('notes')), is_active: data.get('is_active') === 'on' }) }}><FormField label="Default age group" htmlFor="detail-group"><Select id="detail-group" name="default_age_group" defaultValue={value.default_age_group || ''}><option value="">All age groups</option>{asList(groups.data || []).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</Select></FormField><FormField label="Notes" htmlFor="detail-notes"><Textarea id="detail-notes" name="notes" defaultValue={value.notes} /></FormField><label className="flex min-h-11 items-center gap-3"><input type="checkbox" name="is_active" defaultChecked={value.is_active} /> Active</label><MutationStatus mutation={mutation} success="Facilitator saved." /><PermissionGuard require="church-facilitators.manage"><Button><Save /> Save facilitator</Button></PermissionGuard></form></PageSection><PageSection title="Service assignments"><div className="grid gap-2">{asList(assignments.data || []).map((item) => <div className="rounded-lg border p-3" key={item.id}><strong>{item.service_name}</strong><p className="text-sm text-muted-foreground">{friendlyDate(item.service_date)} · <span className="capitalize">{item.role}</span></p></div>)}</div></PageSection></div></div>
}

export function SessionFacilitatorsPage() { return <BranchRequired>{(scope) => <SessionFacilitators scope={scope} />}</BranchRequired> }
function SessionFacilitators({ scope }: { scope: ChurchScope }) {
  const { sessionId } = useParams({ strict: false }) as { sessionId: UUID }; const client = useQueryClient(); const { hasPermission } = useTenant(); const { user } = useAuth()
  const session = useQuery({ queryKey: churchKeys.resource(scope, 'session', sessionId), queryFn: () => churchApi.session(scope, sessionId) })
  const facilitators = useQuery({ queryKey: churchKeys.resource(scope, 'facilitators'), queryFn: () => churchApi.facilitators(scope) })
  const assignments = useQuery({ queryKey: churchKeys.resource(scope, 'assignments', sessionId), queryFn: () => churchApi.assignments(scope, sessionId) })
  const attendance = useQuery({ queryKey: churchKeys.resource(scope, 'facilitator-attendance', sessionId), queryFn: () => churchApi.facilitatorAttendance(scope, sessionId) })
  const [tab, setTab] = useState<'assignments' | 'attendance'>('assignments'); const [search, setSearch] = useState(''); const [selected, setSelected] = useState<Record<UUID, string>>({}); const [assignmentsDirty, setAssignmentsDirty] = useState(false); const [attendanceChanges, setAttendanceChanges] = useState<Record<UUID, AttendanceStatus>>({})
  useEffect(() => { if (assignments.data && !assignmentsDirty) setSelected(Object.fromEntries(asList(assignments.data).map((row) => [row.facilitator, row.role]))) }, [assignments.data, assignmentsDirty])
  const assign = useMutation({ mutationFn: () => churchApi.assignFacilitators(scope, sessionId, Object.entries(selected).map(([facilitator_id, role]) => ({ facilitator_id, role }))), onSuccess: async () => { setAssignmentsDirty(false); await client.invalidateQueries({ queryKey: churchKeys.root(scope) }) } })
  const saveAttendance = useMutation({ mutationFn: () => churchApi.saveFacilitatorAttendance(scope, sessionId, Object.entries(attendanceChanges).map(([facilitator_id, attendance_status]) => ({ facilitator_id, attendance_status }))), onSuccess: () => { setAttendanceChanges({}); void client.invalidateQueries({ queryKey: churchKeys.root(scope) }) } })
  const allFacilitators = asList(facilitators.data || []); const assignedRows = asList(assignments.data || []); const existingAttendance = new Map(asList(attendance.data || []).map((row) => [row.facilitator, row.attendance_status])); const canManage = hasPermission('church-facilitators.manage'); const canRecord = hasPermission('church-attendance.manage')
  const visibleFacilitators = [...allFacilitators].filter((item) => `${item.name} ${item.email} ${item.default_age_group_name || ''}`.toLowerCase().includes(search.toLowerCase())).sort((a, b) => Number(b.id in selected) - Number(a.id in selected) || a.name.localeCompare(b.name))
  const changeAssignment = (id: UUID, checked: boolean) => { setAssignmentsDirty(true); setSelected((value) => { const next = { ...value }; if (checked) next[id] = 'volunteer'; else delete next[id]; return next }) }
  if (session.isLoading) return <div className="page-grid"><Spinner label="Loading service" /></div>
  if (session.error || !session.data) return <div className="page-grid"><ErrorState message={errorMessage(session.error)} onRetry={() => void session.refetch()} /></div>
  const service = session.data
  return <div className="page-grid"><PageHeader title={service.name} description={`${service.event_name} · ${friendlyDate(service.event_date)} · ${friendlyTime(service.start_time)}${service.location ? ` · ${service.location}` : ''}`} /><PageSection><div className="mb-4 flex gap-1 border-b" role="tablist" aria-label="Service facilitator workflow"><button role="tab" aria-selected={tab === 'assignments'} className={`border-b-2 px-4 py-3 text-sm font-semibold ${tab === 'assignments' ? 'border-sky-600 text-foreground' : 'border-transparent text-muted-foreground'}`} onClick={() => setTab('assignments')}>Assignments</button><button role="tab" aria-selected={tab === 'attendance'} className={`border-b-2 px-4 py-3 text-sm font-semibold ${tab === 'attendance' ? 'border-sky-600 text-foreground' : 'border-transparent text-muted-foreground'}`} onClick={() => setTab('attendance')}>Attendance</button></div>{tab === 'assignments' ? <div><div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><FormField label="Search facilitators" htmlFor="facilitator-search"><Input id="facilitator-search" type="search" placeholder="Name, email or age group…" value={search} onChange={(event) => setSearch(event.target.value)} /></FormField><span className="text-sm text-muted-foreground">{Object.keys(selected).length} assigned</span></div>{facilitators.isLoading ? <Spinner /> : facilitators.error ? <ErrorState message={errorMessage(facilitators.error)} onRetry={() => void facilitators.refetch()} /> : !visibleFacilitators.length ? <EmptyState title="No facilitators found" /> : <><div className="hidden overflow-hidden rounded-lg border md:block"><table className="w-full text-left text-sm text-slate-950 dark:text-slate-50"><thead className="bg-muted/70"><tr><th className="px-4 py-3">Assigned</th><th className="px-4 py-3">Facilitator</th><th className="px-4 py-3">Age group</th><th className="px-4 py-3">Role</th></tr></thead><tbody>{visibleFacilitators.map((item) => <tr className="border-t" key={item.id}><td className="px-4 py-3"><input aria-label={`Assign ${item.name}`} type="checkbox" className="h-5 w-5" disabled={!canManage} checked={item.id in selected} onChange={(event) => changeAssignment(item.id, event.target.checked)} /></td><td className="px-4 py-3"><strong>{item.name}</strong><span className="block text-xs text-muted-foreground">{item.email}</span></td><td className="px-4 py-3">{item.default_age_group_name || 'All age groups'}</td><td className="px-4 py-3">{item.id in selected ? <Select className="max-w-40" aria-label={`${item.name} role`} disabled={!canManage} value={selected[item.id]} onChange={(event) => { setAssignmentsDirty(true); setSelected((value) => ({ ...value, [item.id]: event.target.value })) }}>{['lead', 'assistant', 'teacher', 'volunteer', 'other'].map((role) => <option value={role} key={role}>{role}</option>)}</Select> : '—'}</td></tr>)}</tbody></table></div><div className="grid gap-3 md:hidden">{visibleFacilitators.map((item) => <article className="rounded-lg border p-4" key={item.id}><label className="flex items-start gap-3"><input aria-label={`Assign ${item.name}`} type="checkbox" className="mt-1 h-5 w-5" disabled={!canManage} checked={item.id in selected} onChange={(event) => changeAssignment(item.id, event.target.checked)} /><span><strong>{item.name}</strong><span className="block text-xs text-muted-foreground">{item.email} · {item.default_age_group_name || 'All age groups'}</span></span></label>{item.id in selected && <Select className="mt-3" aria-label={`${item.name} role`} disabled={!canManage} value={selected[item.id]} onChange={(event) => { setAssignmentsDirty(true); setSelected((value) => ({ ...value, [item.id]: event.target.value })) }}>{['lead', 'assistant', 'teacher', 'volunteer', 'other'].map((role) => <option value={role} key={role}>{role}</option>)}</Select>}</article>)}</div></>}<MutationStatus mutation={assign} success="Assignments saved." />{canManage && <div className="mt-4 flex justify-end"><Button onClick={() => assign.mutate()} disabled={!assignmentsDirty || assign.isPending}><Save /> {assign.isPending ? 'Saving…' : 'Save assignments'}</Button></div>}</div> : <div>{assignmentsDirty && <p role="alert" className="mb-4 rounded-lg bg-amber-50 p-3 text-sm text-amber-900 dark:bg-amber-950 dark:text-amber-100">Save assignment changes before recording attendance.</p>}{assignments.isLoading || attendance.isLoading ? <Spinner /> : assignments.error || attendance.error ? <ErrorState message={errorMessage(assignments.error || attendance.error)} onRetry={() => { void assignments.refetch(); void attendance.refetch() }} /> : !assignedRows.length ? <EmptyState title="No facilitators assigned" description="Assign facilitators in the Assignments tab before recording attendance." /> : <div className="grid gap-3">{assignedRows.map((item) => { const current = attendanceChanges[item.facilitator] || existingAttendance.get(item.facilitator); const editable = canRecord && (canManage || item.facilitator_user === user?.id); return <article className="rounded-lg border p-4" key={item.id}><div className="mb-3 flex items-start justify-between gap-3"><div><strong>{item.facilitator_name}</strong><p className="text-xs capitalize text-muted-foreground">{item.role}</p></div>{!editable && <Badge>Read only</Badge>}</div><div className="grid grid-cols-2 gap-2 sm:grid-cols-4">{statuses.map((statusValue) => <Button key={statusValue} disabled={!editable || assignmentsDirty} variant={current === statusValue ? statusValue === 'absent' ? 'danger' : 'primary' : 'secondary'} className="capitalize" onClick={() => setAttendanceChanges((value) => ({ ...value, [item.facilitator]: statusValue }))}>{statusValue}</Button>)}</div></article> })}</div>}<MutationStatus mutation={saveAttendance} success="Facilitator attendance saved." />{canRecord && <div className="mt-4 flex justify-end"><Button disabled={assignmentsDirty || !Object.keys(attendanceChanges).length || saveAttendance.isPending} onClick={() => saveAttendance.mutate()}><Save /> {saveAttendance.isPending ? 'Saving…' : 'Save attendance'}</Button></div>}</div>}</PageSection></div>
}

export function AbsenteeismPage() { return <BranchRequired>{(scope) => <Absenteeism scope={scope} />}</BranchRequired> }
function Absenteeism({ scope }: { scope: ChurchScope }) {
  const [range, setRange] = useState({ from: '', to: '' })
  const [search, setSearch] = useState('')
  const query = useQuery({ queryKey: churchKeys.resource(scope, 'repeated-absentees', range), queryFn: () => churchApi.repeatedAbsentees(scope, range.from, range.to) })
  const columns: DataColumn<RepeatedAbsentee>[] = [{ key: 'child', header: 'Child', cell: (row) => <Link to="/church/children/$childId" params={{ childId: row.child_id }} className="font-semibold text-primary">{row.child_name}</Link> }, { key: 'group', header: 'Age group', cell: (row) => row.age_group }, { key: 'attended', header: 'Attended', cell: (row) => row.attended }, { key: 'missed', header: 'Missed', cell: (row) => row.missed, sortValue: (row) => row.missed }, { key: 'rate', header: 'Attendance', cell: (row) => row.attendance_percentage == null ? '—' : `${row.attendance_percentage}%` }]
  return <div className="page-grid"><PageHeader title="Absenteeism" description="Repeated absences from finalized Sunday services." /><PageSection><div className="mb-4 grid gap-3 md:grid-cols-3"><FormField label="From" htmlFor="absence-from"><Input id="absence-from" type="date" value={range.from} onChange={(event) => setRange((value) => ({ ...value, from: event.target.value }))} /></FormField><FormField label="To" htmlFor="absence-to"><Input id="absence-to" type="date" value={range.to} onChange={(event) => setRange((value) => ({ ...value, to: event.target.value }))} /></FormField><FormField label="Search" htmlFor="absence-search"><Input id="absence-search" type="search" placeholder="Child or age group…" value={search} onChange={(event) => setSearch(event.target.value)} /></FormField></div><DataView rows={query.data || []} columns={columns} getRowId={(row) => row.child_id} mobileSummary={(row) => <><strong>{row.child_name}</strong><p className="text-sm text-muted-foreground">{row.age_group}</p></>} mobileDetails={(row) => <span>{row.missed} missed · {row.attendance_percentage ?? '—'}% attendance</span>} searchableText={(row) => `${row.child_name} ${row.age_group}`} searchValue={search} onSearchValueChange={setSearch} showSearchInput={false} loading={query.isLoading} error={query.error ? errorMessage(query.error) : undefined} emptyTitle="No repeated absences in this period" /></PageSection></div>
}
